import{_ as i,o as l,c as r,a2 as t}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Version 1.0.0.14 Launched","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-1.0.0.14-launched.md","filePath":"change-log/release/version-1.0.0.14-launched.md"}'),n={name:"change-log/release/version-1.0.0.14-launched.md"};function o(a,e,s,d,c,u){return l(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="version-1-0-0-14-launched" tabindex="-1">Version 1.0.0.14 Launched <a class="header-anchor" href="#version-1-0-0-14-launched" aria-label="Permalink to &quot;Version 1.0.0.14 Launched&quot;">​</a></h1><p>6th Dec 2024</p><p><strong>Major Features</strong></p><ol><li><strong>API Analyzer Mode</strong><ul><li>New analyze/live mode toggle for strategy testing.</li><li>Real-time order validation without actual execution.</li><li>Strategy performance monitoring and analysis.</li><li>Garden theme in analyze mode for clear visual distinction.</li><li>Mode switcher with status badge for easy toggling.</li></ul></li><li><strong>Enhanced Security</strong><ul><li>TOTP-based two-factor authentication.</li><li>QR code generation for easy TOTP setup.</li><li>Secure password reset with multi-step verification.</li><li>Rate limiting for password reset (3 attempts/hour).</li><li>Improved security hashing mechanisms.</li></ul></li><li><strong>New Broker Integration</strong><ul><li>Added Shoonya broker support.</li><li>Complete order management capabilities.</li><li>Real-time data integration.</li><li>Portfolio tracking support.</li></ul></li><li><strong>User Experience Improvements</strong><ul><li>Garden theme for analyze mode, Light/Dark for live mode.</li><li>API key requirement notification for TradingView access.</li><li>Visual mode indicators for analyze/live states.</li><li>Copyable TOTP secret key for manual entry.</li><li>Improved error messages and validations.</li></ul></li><li><strong>Technical Improvements</strong><ul><li>Centralized version management through version.py.</li><li>Removed version from environment variables.</li><li>Enhanced version checking mechanism.</li><li>Improved environment variable validation.</li><li>Better error handling and user feedback.</li></ul></li></ol><p><strong>Detailed Changes</strong></p><p><strong>Security Enhancements</strong></p><ul><li>Multi-step password reset flow: <ul><li>TOTP verification.</li><li>Secure token generation.</li><li>New password setup.</li></ul></li><li>Session-based token validation.</li><li>Enhanced rate limiting protection.</li></ul><p><strong>TOTP Implementation</strong></p><ul><li>QR code generation from TOTP URI.</li><li>Manual secret key entry option.</li><li>Copyable secret key display.</li><li>Optional TOTP setup during installation for forgot password</li></ul><p><strong>UI/UX Updates</strong></p><ul><li>Distinct themes for analyze/live modes.</li><li>Clear mode indicators.</li><li>Improved navigation.</li><li>Enhanced error messaging.</li><li>Better user guidance.</li></ul><p><strong>System Improvements</strong></p><ul><li>Centralized version control.</li><li>Improved configuration management.</li><li>Enhanced validation systems.</li><li>Better error handling.</li><li>Streamlined setup process.</li></ul><h4 id="password-meter" tabindex="-1">Password Meter <a class="header-anchor" href="#password-meter" aria-label="Permalink to &quot;Password Meter&quot;">​</a></h4><ul><li>Added a password strength meter in the setup section.</li><li>Provides real-time feedback on password strength.</li><li>Encourages users to create stronger, more secure passwords.</li></ul><p><strong>Notes</strong></p><ul><li>TOTP setup is optional but recommended for account security.</li><li>Analyze mode is for testing only, not paper trading.</li><li>Garden theme indicates analyze mode operation.</li><li>Version is now managed through version.py.</li></ul>',17)])])}const g=i(n,[["render",o]]);export{p as __pageData,g as default};
